// CRM Follow-up Automation: core logic (ported from main.py)

// ---- input normaliser (works for Webhook, Form, WhatsApp, Gmail, Sheets and sample data)
const input = $input.all().flatMap(i => {
  const j = i.json || {};
  if (j.messages && Array.isArray(j.messages)) {           // WhatsApp Trigger
    return j.messages.filter(m => m.text).map(m => ({ from: '+' + m.from, text: m.text.body }));
  }
  if (j.Subject !== undefined || j.From !== undefined) {     // Gmail Trigger (simple)
    return [{ from: (j.From || '').replace(/.*<|>.*/g, ''), subject: j.Subject || '', body: j.snippet || j.text || '' }];
  }
  const b = (j.body !== undefined && j.headers !== undefined) ? j.body : j;   // Webhook wraps payload in body
  if (Array.isArray(b)) return b;
  if (b && Array.isArray(b.items)) return b.items;
  return [b];
});

const STALE = { 'new lead': 2, 'discovery call': 4, 'proposal sent': 5, 'negotiation': 3 };
const TPL = { 'new lead': 'Hi {c}, following up on your enquiry about {t}. When is a good time for a quick call?',
  'discovery call': 'Hi {c}, great speaking with you. Here are next steps on {t}. Shall I send a proposal?',
  'proposal sent': 'Hi {c}, checking you received the proposal for {t}. Happy to walk through it or adjust scope.',
  'negotiation': 'Hi {c}, I wanted to close the loop on {t}. Is anything blocking a decision this week?' };
const today = new Date(); today.setHours(0, 0, 0, 0);
const stale = [];
for (const d of input) {
  const st = (d.stage || '').toLowerCase(); if (!(st in STALE)) continue;
  const silent = Math.round((today - new Date(d.last_contact + 'T00:00:00')) / 864e5);
  if (silent > STALE[st]) stale.push({ ...d, silent, priority: Number(d.value) * silent,
    draft: TPL[st].replace('{c}', d.contact).replace('{t}', d.topic) });
}
stale.sort((a, b) => b.priority - a.priority);
const reps = {};
for (const d of stale) (reps[d.owner] = reps[d.owner] || []).push(d);
return Object.entries(reps).map(([rep, ds]) => ({ json: { rep, email: rep.toLowerCase() + '@yourcompany.com', count: ds.length,
  digest: ds.map(d => `${d.company} (${d.stage}, NGN ${Number(d.value).toLocaleString()}, silent ${d.silent} days)\nLast note: ${d.last_note}\nDraft: ${d.draft}`).join('\n\n') } }));
